    public function index(): void { Sesija::zahtevajPrijavu();$filter=trim($_GET['filter']??'');$f=['status'=>$_GET['status']??'','klijentId'=>$_GET['klijentId']??'','voziloId'=>$_GET['voziloId']??'','datumOd'=>$_GET['datumOd']??'','datumDo'=>$_GET['datumDo']??'','minCena'=>$_GET['minCena']??'','maxCena'=>$_GET['maxCena']??''];$svi=(new IznajmljivanjeRepozitorijum())->dajSve($filter,$f);$str=max(1,(int)($_GET['str']??1));$po=10;$ukupno=count($svi);$brojStr=max(1,(int)ceil($ukupno/$po));$str=min($str,$brojStr);$redovi=array_slice($svi,($str-1)*$po,$po);$klijenti=(new KlijentRepozitorijum())->dajSve();$vozilaFilter=(new VoziloRepozitorijum())->dajSve();$poruka=Sesija::uzmiPoruku();require __DIR__.'/../pogledi/iznajmljivanja/index.php'; }
