    public function stampaDokument(): void { Sesija::zahtevajPrijavu();$id=(int)($_GET['id']??0);$zapis=(new IznajmljivanjeRepozitorijum())->dajPoId($id);if(!$zapis)die('Dokument nije pronađen.');require __DIR__.'/../pogledi/stampa/dokument.php'; }
